// db.js - In-memory Postgres seeded with Courses & Enrollments. Do NOT edit this file.
import { newDb } from 'pg-mem'

const SCHEMA = `
  CREATE TABLE courses (
    id          SERIAL PRIMARY KEY,
    title       TEXT NOT NULL,
    instructor  TEXT NOT NULL,
    department  TEXT NOT NULL,
    credits     INTEGER NOT NULL
  );
  CREATE TABLE enrollments (
    id            SERIAL PRIMARY KEY,
    course_id     INTEGER NOT NULL REFERENCES courses(id),
    student_name  TEXT NOT NULL,
    grade_score   INTEGER,
    enrolled_date DATE NOT NULL,
    is_honors     BOOLEAN NOT NULL DEFAULT FALSE
  );
`

const COURSES = [
  ['Web Development', 'Dr. Smith', 'Computer Science', 3],
  ['Data Structures', 'Dr. Smith', 'Computer Science', 4],
  ['Calculus I', 'Prof. Johnson', 'Mathematics', 4],
  ['Linear Algebra', 'Prof. Johnson', 'Mathematics', 3],
  ['Organic Chemistry', 'Dr. Williams', 'Chemistry', 4],
  ['General Physics', 'Dr. Davis', 'Physics', 4],
  ['World History', 'Prof. Miller', 'History', 3],
  ['Ethics & Society', 'Dr. Wilson', 'Philosophy', 3]
]

const STUDENTS = ['Alice', 'Bob', 'Charlie', 'Diana', 'Ethan', 'Fiona', 'George', 'Hannah']

function makeRows(n) {
  let x = 20260912
  const next = () => (x = (x * 1103515245 + 12345) & 0x7fffffff)
  const rows = []
  for (let i = 0; i < n; i++) {
    const bits = () => (next() >>> 8) & 0xffff
    const course_id = 1 + (bits() % COURSES.length)
    const student_name = STUDENTS[bits() % STUDENTS.length]
    // 15% of enrollments have NULL grade_score (ungraded)
    const rawGrade = 60 + (bits() % 41) // 60-100
    const grade_score = (bits() % 100 < 15) ? null : rawGrade
    const month = 1 + (bits() % 6)
    const day = 1 + (bits() % 28)
    const enrolled_date = `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    const is_honors = (bits() % 2 === 0)
    rows.push({ course_id, student_name, grade_score, enrolled_date, is_honors })
  }
  return rows
}

const db = newDb()
db.public.none(SCHEMA)
for (const [title, instructor, department, credits] of COURSES) {
  db.public.none(
    `INSERT INTO courses (title, instructor, department, credits) VALUES ('${title.replace(/'/g, "''")}', '${instructor.replace(/'/g, "''")}', '${department}', ${credits})`
  )
}
for (const r of makeRows(200)) {
  const gradeVal = r.grade_score === null ? 'NULL' : r.grade_score
  db.public.none(
    `INSERT INTO enrollments (course_id, student_name, grade_score, enrolled_date, is_honors) VALUES (${r.course_id}, '${r.student_name}', ${gradeVal}, '${r.enrolled_date}', ${r.is_honors})`
  )
}
const { Pool } = db.adapters.createPg()
export const pool = new Pool()
